const rows = $input.all().map((item) => item.json);

if (!rows.length) {
  throw new Error('Settings sheet is empty. Add at least one row with active=TRUE.');
}

const normalizeBool = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';

const activeRow = rows.find((row) => normalizeBool(row.active ?? row.Active)) || rows[0];

const templateId = String(
  activeRow.creatomateTemplateId ?? activeRow['Creatomate Template ID'] ?? ''
).trim();

if (!templateId || templateId === 'YOUR_CREATOMATE_TEMPLATE_ID') {
  throw new Error('Set a valid creatomateTemplateId in the Settings sheet before running.');
}

return [{
  json: {
    niche: String(activeRow.niche ?? activeRow.Niche ?? 'general').trim(),
    topic: String(activeRow.topic ?? activeRow.Topic ?? '').trim(),
    tone: String(activeRow.tone ?? activeRow.Tone ?? 'energetic').trim(),
    voice: String(activeRow.voice ?? activeRow.Voice ?? 'onyx').trim(),
    privacyStatus: String(activeRow.privacyStatus ?? activeRow['Privacy Status'] ?? 'unlisted').trim(),
    creatomateTemplateId: templateId,
    language: String(activeRow.language ?? activeRow.Language ?? 'English').trim(),
    settingsSource: 'google_sheets',
    settingsRowNotes: String(activeRow.notes ?? activeRow.Notes ?? '').trim(),
    loadedAt: new Date().toISOString()
  }
}];

