const response = $input.first().json;
const usage = response.usage || {};
const promptTokens = usage.prompt_tokens || 0;
const completionTokens = usage.completion_tokens || 0;
const totalTokens = usage.total_tokens || (promptTokens + completionTokens);

const inputRate = 0.00000015;
const outputRate = 0.0000006;
const estimatedCostUsd = (promptTokens * inputRate) + (completionTokens * outputRate);

return [{
  json: {
    ...response,
    tokenUsage: {
      node: 'Generate Script (OpenAI)',
      model: response.model || 'gpt-4o-mini',
      promptTokens,
      completionTokens,
      totalTokens,
      estimatedCostUsd: Number(estimatedCostUsd.toFixed(6))
    }
  }
}];

const config = $('Normalize Settings').first().json;
const tokenUsage = $input.first().json.tokenUsage || {};
const content = $input.first().json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('OpenAI returned no script content');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('Failed to parse OpenAI JSON: ' + error.message);
}

const required = ['title', 'hook', 'script', 'imagePrompt', 'description', 'tags'];
for (const key of required) {
  if (!parsed[key]) {
    throw new Error('Missing field in AI response: ' + key);
  }
}

const tags = Array.isArray(parsed.tags) ? parsed.tags : String(parsed.tags).split(',').map((t) => t.trim());
const description = parsed.description.includes('#Shorts')
  ? parsed.description
  : parsed.description + '\n\n#Shorts';

const wordCount = parsed.script.split(/\s+/).filter(Boolean).length;
if (wordCount < 110 || wordCount > 160) {
  throw new Error(`Script length out of range (${wordCount} words). Target 125-145 words for 50-55s pacing.`);
}

return [{
  json: {
    ...config,
    title: String(parsed.title).slice(0, 100),
    hook: parsed.hook,
    script: parsed.script,
    imagePrompt: parsed.imagePrompt,
    description,
    tags,
    wordCount,
    tokenUsage
  }
}];

const scriptData = $('Parse Script JSON').first().json;
const imageResponse = $input.first().json;

const imageUrl = imageResponse.data?.[0]?.url;
if (!imageUrl) {
  throw new Error('No image URL returned from OpenAI image generation');
}

const estimatedImageCostUsd = 0.04;

return [{
  json: {
    ...scriptData,
    backgroundImageUrl: imageUrl,
    tokenUsage: {
      ...scriptData.tokenUsage,
      imageGeneration: {
        node: 'Generate Background (DALL-E)',
        estimatedCostUsd: estimatedImageCostUsd
      },
      runEstimatedCostUsd: Number(((scriptData.tokenUsage?.estimatedCostUsd || 0) + estimatedImageCostUsd).toFixed(6))
    }
  }
}];

const scriptData = $('Log Image Cost Estimate').first().json;
const voiceItem = $('Generate Voiceover (OpenAI TTS)').first();

const binary = voiceItem.binary?.voiceover;
if (!binary?.data) {
  throw new Error('No voiceover binary returned from OpenAI TTS');
}

const ttsEstimatedCostUsd = 0.015;
const audioDataUri = `data:${binary.mimeType || 'audio/mpeg'};base64,${binary.data}`;

const tokenUsage = {
  ...scriptData.tokenUsage,
  tts: {
    node: 'Generate Voiceover (OpenAI TTS)',
    estimatedCostUsd: ttsEstimatedCostUsd
  },
  runEstimatedCostUsd: Number(((scriptData.tokenUsage?.runEstimatedCostUsd || 0) + ttsEstimatedCostUsd).toFixed(6))
};

return [{
  json: {
    ...scriptData,
    audioDataUri,
    tokenUsage,
    creatomateModifications: {
      'Voice-Audio': audioDataUri,
      'Background-Image': scriptData.backgroundImageUrl,
      'Hook-Text': scriptData.hook,
      'Caption-Text': scriptData.script
    }
  }
}];
